components.css:
@keyframes ds-hover-pulse { 0%,100% { scale:1; opacity:1; } 50% { scale:1.3; opacity:.65; } }
.ds-hover-button { position:relative; isolation:isolate; overflow:hidden; flex-shrink:0; min-height:36px; padding:6px 16px; border-radius:999px; background:#FFFFFF; color:#B94E3A; border:1px solid #B94E3A; font:600 14px/1.5 Roboto,sans-serif; letter-spacing:.6px; text-transform:uppercase; white-space:nowrap; cursor:pointer; box-shadow:none; }
.ds-hover-button::before { content:""; position:absolute; left:16px; top:calc(50% - 4px); width:8px; height:8px; border-radius:50%; background:#B94E3A; transform:scale(1); animation:ds-hover-pulse 2s ease-in-out infinite; transition:transform 550ms cubic-bezier(.4,0,.2,1); pointer-events:none; }
.ds-hover-label { position:relative; display:inline-block; padding-left:14px; transition:transform 400ms cubic-bezier(.4,0,.2,1),opacity 250ms ease; }
.ds-hover-overlay { position:absolute; inset:0; display:flex; align-items:center; justify-content:center; gap:6px; color:#FFFFFF; opacity:0; transform:translateX(32px); transition:transform 450ms cubic-bezier(.16,1,.3,1),opacity 250ms ease; pointer-events:none; }
.ds-hover-button:is(:hover,:active,:focus-visible,:disabled) { box-shadow:none; }
.ds-hover-button:focus-visible { outline:3px solid #B94E3A; outline-offset:3px; }
.ds-hover-button:focus-visible::before { animation:none; transform:scale(45); }
.ds-hover-button:focus-visible .ds-hover-label { transform:translateX(48px); opacity:0; }
.ds-hover-button:focus-visible .ds-hover-overlay { transform:translateX(0); opacity:1; transition-delay:150ms; }
@media (hover:hover) and (pointer:fine) { .ds-hover-button:hover::before { animation:none; transform:scale(45); } .ds-hover-button:hover .ds-hover-label { transform:translateX(48px); opacity:0; } .ds-hover-button:hover .ds-hover-overlay { transform:translateX(0); opacity:1; transition-delay:150ms; } }
@media (max-width:899.95px) { .ds-hover-button { padding:6px 12px; font-size:12px; } .ds-hover-button::before { left:12px; } }
@media (prefers-reduced-motion:reduce) { .ds-hover-button::before { animation:none; } .ds-hover-button::before,.ds-hover-label,.ds-hover-overlay { transition:none; } }
